$InPath = 'C:\Users\Administrator\Desktop\InPath'
$OutPath = 'C:\Users\Administrator\Desktop\OutPath'
$Filter = '*.png'
$name = '48pics'
Get-ChildItem -Path $InPath -Filter $Filter |
ForEach-Object {
if($j -gt 4) {
$j=1;
$i++;
}
$extension = $_.Extension;
$newName = '{0}_{1}_{2}{3}' -f $name, $i, $j, $extension;
$Path = '{0}\{1}' -f $OutPath, $newName;
$j++;
Write-Host $newName;
copy-item $_.FullName -destination $Path
}
